// Example 1: Inline Function Definition in a Header
// Compiler emits the definition into a section
// marked for duplication elimination (COMDAT/Link-Once).

inline int square(int x) {
    return x * x;
}

// Every TU calling square() gets a definition.
// Linker resolves the redundancy.

// Example 2: Template Instantiation Definition
// Templates require definitions in the header,
// automatically generating COMDAT/Link-Once sections.

template <typename T>
T add(T a, T b) {
    return a + b;
}

// TU_A uses add<float>
// TU_B uses add<float>
// The linker keeps only one definition of add<float>.

// Example 3: Template Static Data Member Definition
// Required outside the class, usually in the header.

template <typename T>
struct Counter {
    static int count;
};

template <typename T>
int Counter<T>::count = 0; // COMDAT Data Section
